package net.civeira.phylax.feature.observe.observedissuealias.domain;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedIssueAliasChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_issue_alias_change_set_builder() {
    ObservedIssueAliasChangeSet one =
        new ObservedIssueAliasChangeSet().uid("one").origin(ObservedSourceReference.of("one"))
            .fingerprint("one").issue(ObservedIssueReference.of("one")).version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedSourceReference.of("one"), one.getOrigin().get(),
        "Value must equals to the intial value");
    one.origin(ObservedSourceReference.of("two"));
    Assertions.assertEquals(ObservedSourceReference.of("two"), one.getOrigin().get(),
        "Value must equals to the assigned value");
    one.unset("origin");
    Assertions.assertFalse(one.getOrigin().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getFingerprint().get(),
        "Value must equals to the intial value");
    one.fingerprint("two");
    Assertions.assertEquals("two", one.getFingerprint().get(),
        "Value must equals to the assigned value");
    one.unset("fingerprint");
    Assertions.assertFalse(one.getFingerprint().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedIssueReference.of("one"), one.getIssue().get(),
        "Value must equals to the intial value");
    one.issue(ObservedIssueReference.of("two"));
    Assertions.assertEquals(ObservedIssueReference.of("two"), one.getIssue().get(),
        "Value must equals to the assigned value");
    one.unset("issue");
    Assertions.assertFalse(one.getIssue().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
